void
bcm_server_cosq_stat_config_get(cpudb_key_t r_cpu, uint8 *r_pkt, void *r_cookie)
{
	uint8	*r_pp;
	uint32	r_seq;
	int	r_ret;
	int	r_i;
	int	unit;
	int	stat_count;
	bcm_cosq_stat_t *	r_p_stat_array;

	r_pp = r_pkt;
	BCM_UNPACK_U32(r_pp, r_seq);
	r_pp = r_pkt + BCM_RPC_HLEN;
	r_ret = BCM_E_NONE;
	BCM_UNPACK_U32(r_pp, unit);
	BCM_UNPACK_U32(r_pp, stat_count);
	if (*r_pp++ == 1) {
		r_p_stat_array = NULL;
	} else {
		r_p_stat_array = (void *)1;
	}
	if (r_p_stat_array != NULL) {
		r_p_stat_array = sal_alloc(stat_count*sizeof(bcm_cosq_stat_t), "rpc stat_array");
		if (r_p_stat_array == NULL) {
			r_ret = BCM_E_MEMORY;
		}
	}
	bcm_rpc_free(r_pkt, r_cookie);

	if (r_ret == BCM_E_NONE) {
		r_ret = bcm_cosq_stat_config_get(unit, stat_count, r_p_stat_array);
	}

	r_pkt = bcm_rpc_setup('S', (uint32 *)0, 4+(stat_count*4), r_seq, r_ret);
	r_pp = r_pkt + BCM_RPC_HLEN+4;
	if ((r_ret >= 0) && (r_pkt != NULL)) {
		if (r_p_stat_array != NULL) {
			for (r_i = 0; r_i < stat_count; r_i++) {
				BCM_PACK_U32(r_pp, *(r_p_stat_array+r_i));
			}
		}
	}

	if (r_p_stat_array != NULL) {
		sal_free(r_p_stat_array);
	}

	bcm_rpc_reply(r_cpu, r_pkt, r_pp-r_pkt);
}

