void
bcm_server_field_qualify_RangeCheck_get(cpudb_key_t r_cpu, uint8 *r_pkt, void *r_cookie)
{
	uint8	*r_pp;
	uint32	r_seq;
	int	r_ret;
	int	r_i;
	int	unit;
	bcm_field_entry_t	entry;
	int	max_count;
	int	count;
	bcm_field_range_t *	r_p_range;
	int *	r_p_invert;
	int *	r_p_count;

	r_pp = r_pkt;
	BCM_UNPACK_U32(r_pp, r_seq);
	r_pp = r_pkt + BCM_RPC_HLEN;
	r_ret = BCM_E_NONE;
	BCM_UNPACK_U32(r_pp, unit);
	BCM_UNPACK_U32(r_pp, entry);
	BCM_UNPACK_U32(r_pp, max_count);
	if (*r_pp++ == 1) {
		r_p_range = NULL;
	} else {
		r_p_range = (void *)1;
	}
	if (*r_pp++ == 1) {
		r_p_invert = NULL;
	} else {
		r_p_invert = (void *)1;
	}
	if (*r_pp++ == 1) {
		r_p_count = NULL;
	} else {
		r_p_count = &count;
	}
	if (r_p_range != NULL) {
		r_p_range = sal_alloc(max_count*sizeof(bcm_field_range_t), "rpc range");
		if (r_p_range == NULL) {
			r_ret = BCM_E_MEMORY;
		}
	}
	if (r_p_invert != NULL) {
		r_p_invert = sal_alloc(max_count*sizeof(int), "rpc invert");
		if (r_p_invert == NULL) {
			r_ret = BCM_E_MEMORY;
		}
	}
	bcm_rpc_free(r_pkt, r_cookie);

	if (r_ret == BCM_E_NONE) {
		r_ret = bcm_field_qualify_RangeCheck_get(unit, entry, max_count, r_p_range, r_p_invert, r_p_count);
	}

	r_pkt = bcm_rpc_setup('S', (uint32 *)0, 8+(max_count*4)+(max_count*4), r_seq, r_ret);
	r_pp = r_pkt + BCM_RPC_HLEN+4;
	if ((r_ret >= 0) && (r_pkt != NULL)) {
		if (r_p_range != NULL) {
			for (r_i = 0; r_i < max_count; r_i++) {
				BCM_PACK_U32(r_pp, *(r_p_range+r_i));
			}
		}
		if (r_p_invert != NULL) {
			for (r_i = 0; r_i < max_count; r_i++) {
				BCM_PACK_U32(r_pp, *(r_p_invert+r_i));
			}
		}
		if (r_p_count != NULL) {
			BCM_PACK_U32(r_pp, *r_p_count);
		}
	}

	if (r_p_range != NULL) {
		sal_free(r_p_range);
	}
	if (r_p_invert != NULL) {
		sal_free(r_p_invert);
	}

	bcm_rpc_reply(r_cpu, r_pkt, r_pp-r_pkt);
}

