	if (r_ret == BCM_E_NONE) {
		r_ret = bcm_ifa_termination_ports_set(unit, num_ports, r_p_ports);
	}

	if (r_p_ports != NULL) {
		sal_free(r_p_ports);
	}

	r_pkt = bcm_rpc_setup('S', (uint32 *)0, 4, r_seq, r_ret);
	r_pp = r_pkt + BCM_RPC_HLEN+4;

	bcm_rpc_reply(r_cpu, r_pkt, r_pp-r_pkt);
