void
bcm_server_ipmc_rp_get(cpudb_key_t r_cpu, uint8 *r_pkt, void *r_cookie)
{
	uint8	*r_pp;
	uint32	r_seq;
	int	r_ret;
	int	r_i;
	int	unit;
	int	rp_id;
	int	intf_max;
	int	intf_count;
	bcm_if_t *	r_p_intf_array;
	int *	r_p_intf_count;

	r_pp = r_pkt;
	BCM_UNPACK_U32(r_pp, r_seq);
	r_pp = r_pkt + BCM_RPC_HLEN;
	r_ret = BCM_E_NONE;
	BCM_UNPACK_U32(r_pp, unit);
	BCM_UNPACK_U32(r_pp, rp_id);
	BCM_UNPACK_U32(r_pp, intf_max);
	if (*r_pp++ == 1) {
		r_p_intf_array = NULL;
	} else {
		r_p_intf_array = (void *)1;
	}
	if (*r_pp++ == 1) {
		r_p_intf_count = NULL;
	} else {
		r_p_intf_count = &intf_count;
	}
	if (r_p_intf_array != NULL) {
		r_p_intf_array = sal_alloc(intf_max*sizeof(bcm_if_t), "rpc intf_array");
		if (r_p_intf_array == NULL) {
			r_ret = BCM_E_MEMORY;
		}
	}
	bcm_rpc_free(r_pkt, r_cookie);

	if (r_ret == BCM_E_NONE) {
		r_ret = bcm_ipmc_rp_get(unit, rp_id, intf_max, r_p_intf_array, r_p_intf_count);
	}

	r_pkt = bcm_rpc_setup('S', (uint32 *)0, 8+(intf_max*4), r_seq, r_ret);
	r_pp = r_pkt + BCM_RPC_HLEN+4;
	if ((r_ret >= 0) && (r_pkt != NULL)) {
		if (r_p_intf_array != NULL) {
			for (r_i = 0; r_i < intf_max; r_i++) {
				BCM_PACK_U32(r_pp, *(r_p_intf_array+r_i));
			}
		}
		if (r_p_intf_count != NULL) {
			BCM_PACK_U32(r_pp, *r_p_intf_count);
		}
	}

	if (r_p_intf_array != NULL) {
		sal_free(r_p_intf_array);
	}

	bcm_rpc_reply(r_cpu, r_pkt, r_pp-r_pkt);
}

