void
bcm_server_l2_addr_delete_by_vlan_gport_multi(cpudb_key_t r_cpu, uint8 *r_pkt, void *r_cookie)
{
	uint8	*r_pp;
	uint32	r_seq;
	int	r_ret;
	int	r_i;
	int	unit;
	uint32	flags;
	int	num_pairs;
	bcm_vlan_t *	r_p_vlan;
	bcm_gport_t *	r_p_gport;

	r_pp = r_pkt;
	BCM_UNPACK_U32(r_pp, r_seq);
	r_pp = r_pkt + BCM_RPC_HLEN;
	r_ret = BCM_E_NONE;
	BCM_UNPACK_U32(r_pp, unit);
	BCM_UNPACK_U32(r_pp, flags);
	BCM_UNPACK_U32(r_pp, num_pairs);
	if (*r_pp++ == 1) {
		r_p_vlan = NULL;
	} else {
		r_p_vlan = sal_alloc(num_pairs*sizeof(bcm_vlan_t), "rpc vlan");
		if (r_p_vlan == NULL) {
			r_ret = BCM_E_MEMORY;
		} else {
			for (r_i = 0; r_i < num_pairs; r_i++) {
				BCM_UNPACK_U16(r_pp, *(r_p_vlan+r_i));
			}
		}
	}
	if (*r_pp++ == 1) {
		r_p_gport = NULL;
	} else {
		r_p_gport = sal_alloc(num_pairs*sizeof(bcm_gport_t), "rpc gport");
		if (r_p_gport == NULL) {
			r_ret = BCM_E_MEMORY;
		} else {
			for (r_i = 0; r_i < num_pairs; r_i++) {
				BCM_UNPACK_U32(r_pp, *(r_p_gport+r_i));
			}
		}
	}
	bcm_rpc_free(r_pkt, r_cookie);

	if (r_ret == BCM_E_NONE) {
		r_ret = bcm_l2_addr_delete_by_vlan_gport_multi(unit, flags, num_pairs, r_p_vlan, r_p_gport);
	}

	if (r_p_vlan != NULL) {
		sal_free(r_p_vlan);
	}
	if (r_p_gport != NULL) {
		sal_free(r_p_gport);
	}

	r_pkt = bcm_rpc_setup('S', (uint32 *)0, 4, r_seq, r_ret);
	r_pp = r_pkt + BCM_RPC_HLEN+4;

	bcm_rpc_reply(r_cpu, r_pkt, r_pp-r_pkt);
}

