void
bcm_server_l3_route_stat_multi_get(cpudb_key_t r_cpu, uint8 *r_pkt, void *r_cookie)
{
	uint8	*r_pp;
	uint32	r_seq;
	int	r_ret;
	int	r_i;
	int	unit;
	bcm_l3_route_t	info;
	int	nstat;
	bcm_l3_route_t *	r_p_info;
	bcm_l3_route_stat_t *	r_p_stat_arr;
	uint64 *	r_p_value_arr;

	r_pp = r_pkt;
	BCM_UNPACK_U32(r_pp, r_seq);
	r_pp = r_pkt + BCM_RPC_HLEN;
	r_ret = BCM_E_NONE;
	BCM_UNPACK_U32(r_pp, unit);
	if (*r_pp++ == 1) {
		r_p_info = NULL;
	} else {
		r_p_info = &info;
		r_pp = _bcm_unpack_l3_route(r_pp, r_p_info);
	}
	BCM_UNPACK_U32(r_pp, nstat);
	if (*r_pp++ == 1) {
		r_p_stat_arr = NULL;
	} else {
		r_p_stat_arr = sal_alloc(nstat*sizeof(bcm_l3_route_stat_t), "rpc stat_arr");
		if (r_p_stat_arr == NULL) {
			r_ret = BCM_E_MEMORY;
		} else {
			for (r_i = 0; r_i < nstat; r_i++) {
				BCM_UNPACK_U32(r_pp, *(r_p_stat_arr+r_i));
			}
		}
	}
	if (*r_pp++ == 1) {
		r_p_value_arr = NULL;
	} else {
		r_p_value_arr = (void *)1;
	}
	if (r_p_value_arr != NULL) {
		r_p_value_arr = sal_alloc(nstat*sizeof(uint64), "rpc value_arr");
		if (r_p_value_arr == NULL) {
			r_ret = BCM_E_MEMORY;
		}
	}
	bcm_rpc_free(r_pkt, r_cookie);

	if (r_ret == BCM_E_NONE) {
		r_ret = bcm_l3_route_stat_multi_get(unit, r_p_info, nstat, r_p_stat_arr, r_p_value_arr);
	}

	if (r_p_stat_arr != NULL) {
		sal_free(r_p_stat_arr);
	}

	r_pkt = bcm_rpc_setup('S', (uint32 *)0, 4+(nstat*8), r_seq, r_ret);
	r_pp = r_pkt + BCM_RPC_HLEN+4;
	if ((r_ret >= 0) && (r_pkt != NULL)) {
		if (r_p_value_arr != NULL) {
			for (r_i = 0; r_i < nstat; r_i++) {
				r_pp = _bcm_pack_uint64(r_pp, r_p_value_arr+r_i);
			}
		}
	}

	if (r_p_value_arr != NULL) {
		sal_free(r_p_value_arr);
	}

	bcm_rpc_reply(r_cpu, r_pkt, r_pp-r_pkt);
}

