{
	uint8	*r_pp;
	uint32	r_seq;
	int	r_ret;
	int	r_i;
	int	unit;
	bcm_gport_t	niv_port;
	int	array_size;
	int	count;
	bcm_niv_egress_t *	r_p_niv_egress_array;
	int *	r_p_count;

	r_pp = r_pkt;
	BCM_UNPACK_U32(r_pp, r_seq);
	r_pp = r_pkt + BCM_RPC_HLEN;
	r_ret = BCM_E_NONE;
	BCM_UNPACK_U32(r_pp, unit);
	BCM_UNPACK_U32(r_pp, niv_port);
	BCM_UNPACK_U32(r_pp, array_size);
	if (*r_pp++ == 1) {
		r_p_niv_egress_array = NULL;
	} else {
		r_p_niv_egress_array = sal_alloc(array_size*sizeof(bcm_niv_egress_t), "rpc niv_egress_array");
		if (r_p_niv_egress_array == NULL) {
			r_ret = BCM_E_MEMORY;
		} else {
			for (r_i = 0; r_i < array_size; r_i++) {
				r_pp = _bcm_unpack_niv_egress(r_pp, r_p_niv_egress_array+r_i);
			}
		}
	}
	if (*r_pp++ == 1) {
		r_p_count = NULL;
	} else {
		r_p_count = &count;
	}
	bcm_rpc_free(r_pkt, r_cookie);

	if (r_ret == BCM_E_NONE) {
		r_ret = bcm_niv_egress_get(unit, niv_port, array_size, r_p_niv_egress_array, r_p_count);
	}

	r_pkt = bcm_rpc_setup('S', (uint32 *)0, 8+(array_size*34), r_seq, r_ret);
	r_pp = r_pkt + BCM_RPC_HLEN+4;
	if ((r_ret >= 0) && (r_pkt != NULL)) {
		if (r_p_niv_egress_array != NULL) {
			for (r_i = 0; r_i < array_size; r_i++) {
				r_pp = _bcm_pack_niv_egress(r_pp, r_p_niv_egress_array+r_i);
			}
		}
		if (r_p_count != NULL) {
			BCM_PACK_U32(r_pp, *r_p_count);
		}
	}

	if (r_p_niv_egress_array != NULL) {
		sal_free(r_p_niv_egress_array);
	}

	bcm_rpc_reply(r_cpu, r_pkt, r_pp-r_pkt);
}

