void
bcm_server_port_gport_egress_get(cpudb_key_t r_cpu, uint8 *r_pkt, void *r_cookie)
{
	uint8	*r_pp;
	uint32	r_seq;
	int	r_ret;
	int	r_i;
	int	unit;
	bcm_gport_t	source_gport;
	uint32	flags;
	int	max_gports;
	int	num_gports;
	uint32 *	r_p_flags;
	bcm_gport_t *	r_p_block_gports;
	int *	r_p_num_gports;

	r_pp = r_pkt;
	BCM_UNPACK_U32(r_pp, r_seq);
	r_pp = r_pkt + BCM_RPC_HLEN;
	r_ret = BCM_E_NONE;
	BCM_UNPACK_U32(r_pp, unit);
	BCM_UNPACK_U32(r_pp, source_gport);
	if (*r_pp++ == 1) {
		r_p_flags = NULL;
	} else {
		r_p_flags = &flags;
	}
	BCM_UNPACK_U32(r_pp, max_gports);
	if (*r_pp++ == 1) {
		r_p_block_gports = NULL;
	} else {
		r_p_block_gports = (void *)1;
	}
	if (*r_pp++ == 1) {
		r_p_num_gports = NULL;
	} else {
		r_p_num_gports = &num_gports;
	}
	if (r_p_block_gports != NULL) {
		r_p_block_gports = sal_alloc(max_gports*sizeof(bcm_gport_t), "rpc block_gports");
		if (r_p_block_gports == NULL) {
			r_ret = BCM_E_MEMORY;
		}
	}
	bcm_rpc_free(r_pkt, r_cookie);

	if (r_ret == BCM_E_NONE) {
		r_ret = bcm_port_gport_egress_get(unit, source_gport, r_p_flags, max_gports, r_p_block_gports, r_p_num_gports);
	}

	r_pkt = bcm_rpc_setup('S', (uint32 *)0, 12+(max_gports*4), r_seq, r_ret);
	r_pp = r_pkt + BCM_RPC_HLEN+4;
	if ((r_ret >= 0) && (r_pkt != NULL)) {
		if (r_p_flags != NULL) {
			BCM_PACK_U32(r_pp, *r_p_flags);
		}
		if (r_p_block_gports != NULL) {
			for (r_i = 0; r_i < max_gports; r_i++) {
				BCM_PACK_U32(r_pp, *(r_p_block_gports+r_i));
			}
		}
		if (r_p_num_gports != NULL) {
			BCM_PACK_U32(r_pp, *r_p_num_gports);
		}
	}

	if (r_p_block_gports != NULL) {
		sal_free(r_p_block_gports);
	}

	bcm_rpc_reply(r_cpu, r_pkt, r_pp-r_pkt);
}

