void
bcm_server_port_l2_tunnel_payload_tpid_get_all(cpudb_key_t r_cpu, uint8 *r_pkt, void *r_cookie)
{
	uint8	*r_pp;
	uint32	r_seq;
	int	r_ret;
	int	r_i;
	int	unit;
	bcm_port_t	port;
	int	size;
	int	count;
	uint16 *	r_p_tpid_array;
	int *	r_p_color_array;
	int *	r_p_count;

	r_pp = r_pkt;
	BCM_UNPACK_U32(r_pp, r_seq);
	r_pp = r_pkt + BCM_RPC_HLEN;
	r_ret = BCM_E_NONE;
	BCM_UNPACK_U32(r_pp, unit);
	BCM_UNPACK_U32(r_pp, port);
	BCM_UNPACK_U32(r_pp, size);
	if (*r_pp++ == 1) {
		r_p_tpid_array = NULL;
	} else {
		r_p_tpid_array = (void *)1;
	}
	if (*r_pp++ == 1) {
		r_p_color_array = NULL;
	} else {
		r_p_color_array = (void *)1;
	}
	if (*r_pp++ == 1) {
		r_p_count = NULL;
	} else {
		r_p_count = &count;
	}
	if (r_p_tpid_array != NULL) {
		r_p_tpid_array = sal_alloc(size*sizeof(uint16), "rpc tpid_array");
		if (r_p_tpid_array == NULL) {
			r_ret = BCM_E_MEMORY;
		}
	}
	if (r_p_color_array != NULL) {
		r_p_color_array = sal_alloc(size*sizeof(int), "rpc color_array");
		if (r_p_color_array == NULL) {
			r_ret = BCM_E_MEMORY;
		}
	}
	bcm_rpc_free(r_pkt, r_cookie);

	if (r_ret == BCM_E_NONE) {
		r_ret = bcm_port_l2_tunnel_payload_tpid_get_all(unit, port, size, r_p_tpid_array, r_p_color_array, r_p_count);
	}

	r_pkt = bcm_rpc_setup('S', (uint32 *)0, 8+(size*2)+(size*4), r_seq, r_ret);
	r_pp = r_pkt + BCM_RPC_HLEN+4;
	if ((r_ret >= 0) && (r_pkt != NULL)) {
		if (r_p_tpid_array != NULL) {
			for (r_i = 0; r_i < size; r_i++) {
				BCM_PACK_U16(r_pp, *(r_p_tpid_array+r_i));
			}
		}
		if (r_p_color_array != NULL) {
			for (r_i = 0; r_i < size; r_i++) {
				BCM_PACK_U32(r_pp, *(r_p_color_array+r_i));
			}
		}
		if (r_p_count != NULL) {
			BCM_PACK_U32(r_pp, *r_p_count);
		}
	}

	if (r_p_tpid_array != NULL) {
		sal_free(r_p_tpid_array);
	}
	if (r_p_color_array != NULL) {
		sal_free(r_p_color_array);
	}

	bcm_rpc_reply(r_cpu, r_pkt, r_pp-r_pkt);
}

