{
	uint8	*r_pp;
	uint32	r_seq;
	int	r_ret;
	int	r_i;
	int	unit;
	bcm_port_t	port;
	uint32	flags;
	int	num_map;
	bcm_port_lane_to_serdes_map_t *	r_p_serdes_map;

	r_pp = r_pkt;
	BCM_UNPACK_U32(r_pp, r_seq);
	r_pp = r_pkt + BCM_RPC_HLEN;
	r_ret = BCM_E_NONE;
	BCM_UNPACK_U32(r_pp, unit);
	BCM_UNPACK_U32(r_pp, port);
	BCM_UNPACK_U32(r_pp, flags);
	BCM_UNPACK_U32(r_pp, num_map);
	if (*r_pp++ == 1) {
		r_p_serdes_map = NULL;
	} else {
		r_p_serdes_map = sal_alloc(num_map*sizeof(bcm_port_lane_to_serdes_map_t), "rpc serdes_map");
		if (r_p_serdes_map == NULL) {
			r_ret = BCM_E_MEMORY;
		} else {
			for (r_i = 0; r_i < num_map; r_i++) {
				r_pp = _bcm_unpack_port_lane_to_serdes_map(r_pp, r_p_serdes_map+r_i);
			}
		}
	}
	bcm_rpc_free(r_pkt, r_cookie);

	if (r_ret == BCM_E_NONE) {
		r_ret = bcm_port_pcs_lane_map_set(unit, port, flags, num_map, r_p_serdes_map);
	}

	if (r_p_serdes_map != NULL) {
		sal_free(r_p_serdes_map);
	}

	r_pkt = bcm_rpc_setup('S', (uint32 *)0, 4, r_seq, r_ret);
	r_pp = r_pkt + BCM_RPC_HLEN+4;

	bcm_rpc_reply(r_cpu, r_pkt, r_pp-r_pkt);
}

