{
	uint8	*r_pp;
	uint32	r_seq;
	int	r_ret;
	int	r_i;
	int	unit;
	bcm_port_t	port;
	bcm_port_ber_proj_params_t	ber_proj;
	int	max_errcnt;
	int	actual_errcnt;
	bcm_port_ber_proj_params_t *	r_p_ber_proj;
	bcm_port_ber_proj_analyzer_errcnt_t *	r_p_errcnt_array;
	int *	r_p_actual_errcnt;

	r_pp = r_pkt;
	BCM_UNPACK_U32(r_pp, r_seq);
	r_pp = r_pkt + BCM_RPC_HLEN;
	r_ret = BCM_E_NONE;
	BCM_UNPACK_U32(r_pp, unit);
	BCM_UNPACK_U32(r_pp, port);
	if (*r_pp++ == 1) {
		r_p_ber_proj = NULL;
	} else {
		r_p_ber_proj = &ber_proj;
		r_pp = _bcm_unpack_port_ber_proj_params(r_pp, r_p_ber_proj);
	}
	BCM_UNPACK_U32(r_pp, max_errcnt);
	if (*r_pp++ == 1) {
		r_p_errcnt_array = NULL;
	} else {
		r_p_errcnt_array = (void *)1;
	}
	if (*r_pp++ == 1) {
		r_p_actual_errcnt = NULL;
	} else {
		r_p_actual_errcnt = &actual_errcnt;
	}
	if (r_p_errcnt_array != NULL) {
		r_p_errcnt_array = sal_alloc(max_errcnt*sizeof(bcm_port_ber_proj_analyzer_errcnt_t), "rpc errcnt_array");
		if (r_p_errcnt_array == NULL) {
			r_ret = BCM_E_MEMORY;
		}
	}
	bcm_rpc_free(r_pkt, r_cookie);

	if (r_ret == BCM_E_NONE) {
		r_ret = bcm_port_post_ber_proj_get(unit, port, r_p_ber_proj, max_errcnt, r_p_errcnt_array, r_p_actual_errcnt);
	}

	r_pkt = bcm_rpc_setup('S', (uint32 *)0, 8+(max_errcnt*76), r_seq, r_ret);
	r_pp = r_pkt + BCM_RPC_HLEN+4;
	if ((r_ret >= 0) && (r_pkt != NULL)) {
		if (r_p_errcnt_array != NULL) {
			for (r_i = 0; r_i < max_errcnt; r_i++) {
				r_pp = _bcm_pack_port_ber_proj_analyzer_errcnt(r_pp, r_p_errcnt_array+r_i);
			}
		}
		if (r_p_actual_errcnt != NULL) {
			BCM_PACK_U32(r_pp, *r_p_actual_errcnt);
		}
	}

	if (r_p_errcnt_array != NULL) {
		sal_free(r_p_errcnt_array);
	}

	bcm_rpc_reply(r_cpu, r_pkt, r_pp-r_pkt);
}

