void
bcm_server_compat6516_vxlan_port_get_all(cpudb_key_t r_cpu, uint8 *r_pkt, void *r_cookie)
{
	uint8	*r_pp;
	uint32	r_seq;
	int	r_ret;
	int	r_i;
	int	unit;
	bcm_vpn_t	l2vpn;
	int	port_max;
	int	port_count;
	bcm_compat6516_vxlan_port_t *	r_p_port_array;
	int *	r_p_port_count;

	r_pp = r_pkt;
	BCM_UNPACK_U32(r_pp, r_seq);
	r_pp = r_pkt + BCM_RPC_HLEN;
	r_ret = BCM_E_NONE;
	BCM_UNPACK_U32(r_pp, unit);
	BCM_UNPACK_U16(r_pp, l2vpn);
	BCM_UNPACK_U32(r_pp, port_max);
	if (*r_pp++ == 1) {
		r_p_port_array = NULL;
	} else {
		r_p_port_array = sal_alloc(port_max*sizeof(bcm_compat6516_vxlan_port_t), "rpc port_array");
		if (r_p_port_array == NULL) {
			r_ret = BCM_E_MEMORY;
		} else {
			for (r_i = 0; r_i < port_max; r_i++) {
				BCM_UNPACK_U32(r_pp, (r_p_port_array+r_i)->vxlan_port_id);
				BCM_UNPACK_U32(r_pp, (r_p_port_array+r_i)->flags);
				BCM_UNPACK_U32(r_pp, (r_p_port_array+r_i)->if_class);
				BCM_UNPACK_U16(r_pp, (r_p_port_array+r_i)->int_pri);
				BCM_UNPACK_U8(r_pp, (r_p_port_array+r_i)->pkt_pri);
				BCM_UNPACK_U8(r_pp, (r_p_port_array+r_i)->pkt_cfi);
				BCM_UNPACK_U16(r_pp, (r_p_port_array+r_i)->egress_service_tpid);
				BCM_UNPACK_U16(r_pp, (r_p_port_array+r_i)->egress_service_vlan);
				BCM_UNPACK_U16(r_pp, (r_p_port_array+r_i)->mtu);
				BCM_UNPACK_U32(r_pp, (r_p_port_array+r_i)->match_port);
				BCM_UNPACK_U32(r_pp, (r_p_port_array+r_i)->criteria);
				BCM_UNPACK_U16(r_pp, (r_p_port_array+r_i)->match_vlan);
				BCM_UNPACK_U16(r_pp, (r_p_port_array+r_i)->match_inner_vlan);
				BCM_UNPACK_U32(r_pp, (r_p_port_array+r_i)->egress_tunnel_id);
				BCM_UNPACK_U32(r_pp, (r_p_port_array+r_i)->match_tunnel_id);
				BCM_UNPACK_U32(r_pp, (r_p_port_array+r_i)->egress_if);
				BCM_UNPACK_U32(r_pp, (r_p_port_array+r_i)->network_group_id);
				BCM_UNPACK_U32(r_pp, (r_p_port_array+r_i)->vnid);
				BCM_UNPACK_U32(r_pp, (r_p_port_array+r_i)->qos_map_id);
				BCM_UNPACK_U8(r_pp, (r_p_port_array+r_i)->tunnel_pkt_pri);
				BCM_UNPACK_U8(r_pp, (r_p_port_array+r_i)->tunnel_pkt_cfi);
			}
		}
	}
	if (*r_pp++ == 1) {
		r_p_port_count = NULL;
	} else {
		r_p_port_count = &port_count;
		BCM_UNPACK_U32(r_pp, *r_p_port_count);
	}
	bcm_rpc_free(r_pkt, r_cookie);

	if (r_ret == BCM_E_NONE) {
		r_ret = bcm_compat6516_vxlan_port_get_all(unit, l2vpn, port_max, r_p_port_array, r_p_port_count);
	}

	if (r_p_port_array != NULL) {
		sal_free(r_p_port_array);
	}

	r_pkt = bcm_rpc_setup('S', (uint32 *)0, 4, r_seq, r_ret);
	r_pp = r_pkt + BCM_RPC_HLEN+4;

	bcm_rpc_reply(r_cpu, r_pkt, r_pp-r_pkt);
}

