				BCM_PACK_U32(r_pp, (r_p_port_array+r_i)->criteria);
				BCM_PACK_U16(r_pp, (r_p_port_array+r_i)->match_vlan);
				BCM_PACK_U16(r_pp, (r_p_port_array+r_i)->match_inner_vlan);
				BCM_PACK_U32(r_pp, (r_p_port_array+r_i)->match_label);
				BCM_PACK_U32(r_pp, (r_p_port_array+r_i)->egress_tunnel_if);
				r_pp = _bcm_pack_mpls_egress_label(r_pp, &(*(r_p_port_array+r_i)).egress_label);
				BCM_PACK_U32(r_pp, (r_p_port_array+r_i)->mtu);
				BCM_PACK_U16(r_pp, (r_p_port_array+r_i)->egress_service_vlan);
				BCM_PACK_U32(r_pp, (r_p_port_array+r_i)->pw_seq_number);
				BCM_PACK_U32(r_pp, (r_p_port_array+r_i)->encap_id);
				BCM_PACK_U32(r_pp, (r_p_port_array+r_i)->ingress_failover_id);
				BCM_PACK_U32(r_pp, (r_p_port_array+r_i)->ingress_failover_port_id);
				BCM_PACK_U32(r_pp, (r_p_port_array+r_i)->failover_id);
				BCM_PACK_U32(r_pp, (r_p_port_array+r_i)->failover_port_id);
				BCM_PACK_U32(r_pp, (r_p_port_array+r_i)->policer_id);
				BCM_PACK_U32(r_pp, (r_p_port_array+r_i)->failover_mc_group);
				BCM_PACK_U32(r_pp, (r_p_port_array+r_i)->pw_failover_id);
				BCM_PACK_U32(r_pp, (r_p_port_array+r_i)->pw_failover_port_id);
				BCM_PACK_U32(r_pp, (r_p_port_array+r_i)->vccv_type);
				BCM_PACK_U32(r_pp, (r_p_port_array+r_i)->network_group_id);
				BCM_PACK_U16(r_pp, (r_p_port_array+r_i)->match_subport_pkt_vid);
				BCM_PACK_U32(r_pp, (r_p_port_array+r_i)->tunnel_id);
				BCM_PACK_U32(r_pp, (r_p_port_array+r_i)->per_flow_queue_base);
				BCM_PACK_U32(r_pp, (r_p_port_array+r_i)->qos_map_id);
				BCM_PACK_U32(r_pp, (r_p_port_array+r_i)->egress_failover_id);
				BCM_PACK_U32(r_pp, (r_p_port_array+r_i)->egress_failover_port_id);
				BCM_PACK_U32(r_pp, (r_p_port_array+r_i)->ecn_map_id);
				BCM_PACK_U32(r_pp, (r_p_port_array+r_i)->class_id);
				BCM_PACK_U32(r_pp, (r_p_port_array+r_i)->egress_class_id);
				BCM_PACK_U32(r_pp, (r_p_port_array+r_i)->inlif_counting_profile);
				r_pp = _bcm_pack_mpls_egress_label(r_pp, &(*(r_p_port_array+r_i)).egress_tunnel_label);
				BCM_PACK_U32(r_pp, (r_p_port_array+r_i)->nof_service_tags);
				BCM_PACK_U32(r_pp, (r_p_port_array+r_i)->ingress_qos_model.ingress_phb);
				BCM_PACK_U32(r_pp, (r_p_port_array+r_i)->ingress_qos_model.ingress_remark);
